def find_graph():
    n = 18
    # Try different color class sizes
    # For 3-colorable, partition vertices into 3 color classes
    # Try 6, 6, 6 first

    color_classes = [list(range(6)), list(range(6, 12)), list(range(12, 18))]

    # Generate all possible edges between different color classes
    possible_edges = []
    for i in range(3):
        for j in range(i+1, 3):
            for u in color_classes[i]:
                for v in color_classes[j]:
                    possible_edges.append((u, v))

    print(f"Total possible edges: {len(possible_edges)}")

    # Now we need to select at least 29 edges such that girth >= 8
    # This means no cycles of length 3, 4, 5, 6, 7

    # Let's use a greedy approach with backtracking
    # Start with empty graph and add edges one by one, checking for short cycles

    def has_short_cycle(edges, new_edge, max_cycle_len=7):
        """Check if adding new_edge creates a cycle of length <= max_cycle_len"""
        # Build adjacency list
        adj = defaultdict(set)
        for u, v in edges:
            adj[u].add(v)
            adj[v].add(u)

        u, v = new_edge
        # Check for cycles through this edge
        # BFS from u to v, avoiding the direct edge
        from collections import deque
        queue = deque([(u, [u])])
        visited = {u}

        while queue:
            node, path = queue.popleft()
            if len(path) > max_cycle_len:
                continue
            for neighbor in adj[node]:
                if neighbor == v and len(path) >= 2:
                    # Found a cycle of length len(path)
                    if len(path) <= max_cycle_len:
                        return True
                if neighbor not in visited and neighbor != v:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))

        return False

    # Try greedy approach
    import random
    random.seed(42)

    best_edges = []

    for trial in range(1000):
        random.shuffle(possible_edges)
        edges = []
        for edge in possible_edges:
            if not has_short_cycle(edges, edge, 7):
                edges.append(edge)
                if len(edges) >= 29:
                    break

        if len(edges) > len(best_edges):
            best_edges = edges[:]
            print(f"Trial {trial}: Found {len(edges)} edges")
            if len(edges) >= 29:
                break

    print(f"Best: {len(best_edges)} edges")
    return best_edges

