import random
from collections import defaultdict

def has_cycle_of_length(edges, length, n):
    """Check if graph has a cycle of given length"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # BFS-based cycle detection
    for start in range(n):
        # BFS to find cycles through start
        queue = [(start, [start])]
        visited_at_depth = {start: 0}

        while queue:
            node, path = queue.pop(0)
            if len(path) > length:
                continue
            for neighbor in adj[node]:
                if neighbor == start and len(path) == length:
                    return True
                if neighbor not in visited_at_depth or visited_at_depth[neighbor] > len(path):
                    if neighbor != start:
                        visited_at_depth[neighbor] = len(path)
                        queue.append((neighbor, path + [neighbor]))

    return False

def check_girth(edges, n, min_girth=8):
    """Check if graph has girth >= min_girth"""
    for length in range(3, min_girth):
        if has_cycle_of_length(edges, length, n):
            return False
    return True

