import random
from collections import defaultdict

def find_graph_with_girth(n, min_edges, girth, num_colors):
    """Find a graph with n vertices, at least min_edges edges, girth >= girth, colorable with num_colors colors"""

    # Try different color class partitions
    best_result = None

    # Try partition 6, 6, 6
    partitions = [
        (list(range(6)), list(range(6, 12)), list(range(12, 18))),
    ]

    # Also try other partitions
    for a in range(4, 8):
        for b in range(4, 8):
            c = 18 - a - b
            if c >= 4 and c <= 8:
                partitions.append((list(range(a)), list(range(a, a+b)), list(range(a+b, 18))))

    for part_a, part_b, part_c in partitions:
        # Possible edges are between different color classes
        possible = []
        for u in part_a:
            for v in part_b:
                possible.append((u, v))
        for u in part_a:
            for v in part_c:
                possible.append((u, v))
        for u in part_b:
            for v in part_c:
                possible.append((u, v))

        # Use iterative deepening / beam search
        for trial in range(2000):
            random.shuffle(possible)
            edges = []
            adj = defaultdict(set)

            for edge in possible:
                u, v = edge
                # Check if adding this edge creates a short cycle
                # BFS from u to find shortest path to v
                from collections import deque
                queue = deque([(u, 0, {u})])
                shortest = float('inf')

                while queue:
                    node, dist, visited = queue.popleft()
                    if dist >= girth - 1:
                        continue
                    for neighbor in adj[node]:
                        if neighbor == v:
                            shortest = min(shortest, dist + 1)
                        elif neighbor not in visited:
                            queue.append((neighbor, dist + 1, visited | {neighbor}))

                if shortest >= girth - 1:  # Adding edge creates cycle of length shortest+1
                    edges.append(edge)
                    adj[u].add(v)
                    adj[v].add(u)

            if len(edges) >= min_edges:
                return edges
            if best_result is None or len(edges) > len(best_result):
                best_result = edges[:]

    return best_result

