import random
from collections import defaultdict

def count_short_cycles(edges, n, max_len=7):
    """Count cycles of length 3 to max_len"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    count = 0
    for start in range(n):
        # DFS to find cycles
        stack = [(start, [start])]
        while stack:
            node, path = stack.pop()
            if len(path) > max_len:
                continue
            for neighbor in sorted(adj[node]):
                if neighbor == start and len(path) >= 3:
                    if len(path) <= max_len:
                        count += 1
                elif neighbor > start and neighbor not in path:  # Avoid duplicates
                    stack.append((neighbor, path + [neighbor]))

    return count // 2  # Each cycle counted twice

def check_girth_fast(edges, n, min_girth=8):
    """Quick check for girth"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for cycles of length 3 to min_girth-1
    for length in range(3, min_girth):
        # Use BFS from each vertex
        for start in range(n):
            queue = [(start, [start])]
            while queue:
                node, path = queue.pop(0)
                if len(path) > length:
                    continue
                for neighbor in adj[node]:
                    if neighbor == start and len(path) == length:
                        return False
                    if neighbor not in path and neighbor > start:
                        queue.append((neighbor, path + [neighbor]))
    return True

