def energy(edges):
    """Lower is better. Penalize short cycles and reward more edges."""
    penalty = 0
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Count short cycles
    for length in range(3, 8):
        for start in range(n):
            queue = [(start, [start])]
            while queue:
                node, path = queue.pop(0)
                if len(path) > length:
                    continue
                for neighbor in adj[node]:
                    if neighbor == start and len(path) == length:
                        penalty += 1000 * (8 - length)  # Heavier penalty for shorter cycles
                    elif neighbor not in path and neighbor > start:
                        queue.append((neighbor, path + [neighbor]))

    return penalty - len(edges) * 10  # Reward more edges

