def find_girth(adj, n):
    """Find the girth of the graph"""
    min_cycle = float('inf')

    for start in range(n):
        # BFS from start
        # Track distance and parent
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        idx = 0

        while idx < len(queue):
            node = queue[idx]
            idx += 1

            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif neighbor != parent[node] and dist[neighbor] >= dist[node]:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

